import{_ as t,o as r,c as d,a2 as a}from"./chunks/framework.z3u3TMv0.js";const p=JSON.parse('{"title":"FreeLLM-Verzeichnis","description":"awesome-freellm-apis / freellm.net Free-LLM-API-Index — Anbieter, Base URL, MiniTavern-Eintrag und Links zu Handbuch-Seiten.","frontmatter":{"title":"FreeLLM-Verzeichnis","description":"awesome-freellm-apis / freellm.net Free-LLM-API-Index — Anbieter, Base URL, MiniTavern-Eintrag und Links zu Handbuch-Seiten.","head":[["meta",{"name":"keywords","content":"Tavern,AI Tavern,MiniTavern,AI Begleiter,AI Freund,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobil,Silly Tavern Android,Silly Tavern iOS,AI Roleplay,Charakterkarte,AI Chat,mobiles AI,Offline-AI,AI Geschichte,lokales LLM,Ollama,LM Studio,Lorebook,Regex,BYOK,Handbuch,Anleitung"}],["meta",{"property":"og:title","content":"FreeLLM-Verzeichnis · MiniTavern Docs"}],["meta",{"property":"og:description","content":"awesome-freellm-apis / freellm.net Free-LLM-API-Index — Anbieter, Base URL, MiniTavern-Eintrag und Links zu Handbuch-Seiten."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/de/free-cloud/freellm"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/de/free-cloud/freellm"}]]},"headers":[],"relativePath":"de/free-cloud/freellm.md","filePath":"de/free-cloud/freellm.md","lastUpdated":1787224147000}'),n={name:"de/free-cloud/freellm.md"};function i(o,e,l,s,h,u){return r(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="freellm-verzeichnis" tabindex="-1">FreeLLM-Verzeichnis <a class="header-anchor" href="#freellm-verzeichnis" aria-label="Permalink to &quot;FreeLLM-Verzeichnis&quot;">​</a></h1><p>Community-Index <strong>kostenloser LLM-APIs</strong>: <a href="https://github.com/open-free-llm-api/awesome-freellm-apis" target="_blank" rel="noreferrer">awesome-freellm-apis</a> (täglich von <a href="https://freellm.net" target="_blank" rel="noreferrer">freellm.net</a> aktualisiert). Dutzende Anbieter, Hunderte Free-Modelle; Kreditkarte, Handy-Verifizierung, Base URL / Key-Links markiert.</p><p><strong>Nutzerkurzfassung für MiniTavern</strong>: Anbieter wählen und Bezug zu bestehenden Handbuch-Seiten / Übersicht. <strong>Modell-IDs, Limits, ob noch free: freellm.net / Herstellerkonsole</strong> (README nennt das Update-Datum).</p><h2 id="website-einstiege" tabindex="-1">Website &amp; Einstiege <a class="header-anchor" href="#website-einstiege" aria-label="Permalink to &quot;Website &amp; Einstiege&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ressource</th><th>Adresse</th></tr></thead><tbody><tr><td>GitHub</td><td><a href="https://github.com/open-free-llm-api/awesome-freellm-apis" target="_blank" rel="noreferrer">open-free-llm-api/awesome-freellm-apis</a></td></tr><tr><td>README 中文</td><td><a href="https://github.com/open-free-llm-api/awesome-freellm-apis/blob/main/README.zh-CN.md" target="_blank" rel="noreferrer">README.zh-CN.md</a></td></tr><tr><td>Online</td><td><a href="https://freellm.net" target="_blank" rel="noreferrer">freellm.net</a> (Browse · Playground · Config Generator)</td></tr><tr><td>API-Key-Verzeichnis</td><td><a href="https://freellm.net/free-llm-api-keys/" target="_blank" rel="noreferrer">freellm.net/free-llm-api-keys</a></td></tr><tr><td>Modellvergleich</td><td><a href="https://freellm.net/compare/" target="_blank" rel="noreferrer">freellm.net/compare</a></td></tr></tbody></table><h2 id="nutzung-mit-minitavern" tabindex="-1">Nutzung (mit MiniTavern) <a class="header-anchor" href="#nutzung-mit-minitavern" aria-label="Permalink to &quot;Nutzung (mit MiniTavern)&quot;">​</a></h2><ol><li>Auf <a href="https://freellm.net" target="_blank" rel="noreferrer">freellm.net</a> oder im Anbieterverzeichnis wählen: <strong>bevorzugt ohne Kreditkarte</strong> (Groq, Gemini, Zhipu Flash).</li><li><strong>Get Key</strong> → registrieren, API Key kopieren.</li><li><strong>Base URL</strong> und <strong>Model ID</strong> (Quick Reference / Best Models) notieren.</li><li>MiniTavern: <strong>Einstellungen → Modelle → Modellverbindung → Neu</strong><ul><li>Handbuch-Seite / App-Preset vorhanden (Tabelle unten) → Seite folgen.</li><li>Sonst <strong>Custom (OpenAI)</strong>, Base URL + Key + Modell-ID → <strong>Testen</strong>.</li></ul></li></ol><p>Allgemein: <a href="/ultra_guides/de/manual/model-link">Modellverbindung</a>. Roleplay: <strong>dialogorientierte</strong> Textmodelle; Coding-Agents oft ungeeignet für lange Plots.</p><table tabindex="0"><thead><tr><th>Punkt</th><th>Hinweis</th></tr></thead><tbody><tr><td>Aufnahmekriterien (offiziell)</td><td>klares Free-Tier (nicht nur Kurztrial), öffentlich, Trial-Credits gekennzeichnet</td></tr><tr><td>Aktualität</td><td>täglich auto; Limits und Listen ändern sich</td></tr><tr><td>Zum Handbuch</td><td>Übersicht/Seiten = «wie in der App»; diese Seite + freellm.net = «welche Anbieter noch»</td></tr></tbody></table><h2 id="bereits-im-handbuch-zuerst-lesen" tabindex="-1">Bereits im Handbuch (zuerst lesen) <a class="header-anchor" href="#bereits-im-handbuch-zuerst-lesen" aria-label="Permalink to &quot;Bereits im Handbuch (zuerst lesen)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Anbieter</th><th>Handbuch</th><th>App-Plattform</th></tr></thead><tbody><tr><td>Agnes AI</td><td><a href="/ultra_guides/de/free-cloud/agnes-ai">Agnes AI</a></td><td>Custom (OpenAI) / Images</td></tr><tr><td>OpenCode Zen</td><td><a href="/ultra_guides/de/free-cloud/opencode-zen">OpenCode Zen</a></td><td>Custom (OpenAI)</td></tr><tr><td>AIHubMix</td><td><a href="/ultra_guides/de/free-cloud/aihubmix">AIHubMix</a></td><td>Custom (OpenAI) / Images</td></tr><tr><td>OpenRouter</td><td><a href="/ultra_guides/de/free-cloud/openrouter">OpenRouter</a></td><td>OpenRouter</td></tr><tr><td>Zhipu / Silicon / Bailian / DeepSeek / Gemini / Groq …</td><td><a href="/ultra_guides/de/free-cloud/">Kostenlose Cloud Übersicht</a></td><td>siehe Abschnitte</td></tr></tbody></table><h2 id="anbieterverzeichnis-dauerhaftes-free-tier-·-kurz" tabindex="-1">Anbieterverzeichnis (dauerhaftes Free-Tier · Kurz) <a class="header-anchor" href="#anbieterverzeichnis-dauerhaftes-free-tier-·-kurz" aria-label="Permalink to &quot;Anbieterverzeichnis (dauerhaftes Free-Tier · Kurz)&quot;">​</a></h2><p>Aus «Permanent Free Tiers» (ca. 2026-08-20). <strong>Anzahl Free-Modelle ändert sich</strong>; vollständige Tabelle: <a href="https://github.com/open-free-llm-api/awesome-freellm-apis" target="_blank" rel="noreferrer">GitHub</a> / <a href="https://freellm.net" target="_blank" rel="noreferrer">freellm.net</a>.</p><table tabindex="0"><thead><tr><th>Anbieter</th><th>~Free-Modelle</th><th>Karte usw.</th><th>Fähigkeiten</th><th>Key</th></tr></thead><tbody><tr><td>NVIDIA NIM</td><td>125</td><td>Handy-Verifizierung</td><td>Text / Bild / Video / Vision …</td><td><a href="https://build.nvidia.com/settings/api-keys" target="_blank" rel="noreferrer">build.nvidia.com</a></td></tr><tr><td>ModelScope</td><td>56</td><td>Registrierung</td><td>Text / Bild / Video / Vision</td><td><a href="https://modelscope.cn/my/myaccesstoken" target="_blank" rel="noreferrer">modelscope.cn</a></td></tr><tr><td>Cloudflare Workers AI</td><td>40</td><td>Nein</td><td>Text / Bild / Code …</td><td><a href="https://dash.cloudflare.com/profile/api-tokens" target="_blank" rel="noreferrer">dash.cloudflare.com</a></td></tr><tr><td>Google Gemini</td><td>17</td><td>Nein</td><td>Text / multimodal</td><td><a href="https://aistudio.google.com/app/apikey" target="_blank" rel="noreferrer">aistudio.google.com</a></td></tr><tr><td>GitHub Models</td><td>16</td><td>Nein</td><td>Text …</td><td><a href="https://github.com/marketplace/models" target="_blank" rel="noreferrer">GitHub Models</a></td></tr><tr><td>LLM7.io</td><td>16</td><td>Nein</td><td>Text / multimodal</td><td><a href="https://token.llm7.io" target="_blank" rel="noreferrer">token.llm7.io</a></td></tr><tr><td>OVHcloud AI Endpoints</td><td>14</td><td>Registrierung</td><td>Text …</td><td><a href="https://www.ovhcloud.com/en/public-cloud/ai-endpoints/catalog/" target="_blank" rel="noreferrer">ovhcloud.com</a></td></tr><tr><td>Ollama Cloud</td><td>13</td><td>Registrierung</td><td>Text / Vision …</td><td><a href="https://ollama.com/settings/keys" target="_blank" rel="noreferrer">ollama.com/settings/keys</a></td></tr><tr><td>Groq</td><td>12</td><td>Nein</td><td>Text</td><td><a href="https://console.groq.com/keys" target="_blank" rel="noreferrer">console.groq.com/keys</a></td></tr><tr><td>Mistral AI</td><td>12</td><td>Nein</td><td>Text</td><td><a href="https://console.mistral.ai/api-keys" target="_blank" rel="noreferrer">console.mistral.ai</a></td></tr><tr><td>Cohere</td><td>12</td><td>Nein</td><td>Text</td><td><a href="https://dashboard.cohere.com/api-keys" target="_blank" rel="noreferrer">dashboard.cohere.com</a></td></tr><tr><td>Kilo Code</td><td>12</td><td>Nein</td><td>Text …</td><td><a href="https://kilo.ai" target="_blank" rel="noreferrer">kilo.ai</a></td></tr><tr><td>OpenCode Zen</td><td>11</td><td>Registrierung</td><td>siehe <a href="/ultra_guides/de/free-cloud/opencode-zen">Seite</a></td><td><a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a></td></tr><tr><td>Cerebras</td><td>8</td><td>Nein</td><td>Text</td><td><a href="https://cloud.cerebras.ai/" target="_blank" rel="noreferrer">cloud.cerebras.ai</a></td></tr><tr><td>Aion Labs</td><td>7</td><td>Registrierung</td><td>Text (inkl. RP)</td><td><a href="https://www.aionlabs.ai" target="_blank" rel="noreferrer">aionlabs.ai</a></td></tr><tr><td>Hugging Face</td><td>7</td><td>Nein</td><td>Text / Code</td><td><a href="https://huggingface.co/settings/tokens" target="_blank" rel="noreferrer">huggingface.co/settings/tokens</a></td></tr><tr><td>Agnes AI</td><td>5</td><td>Registrierung</td><td>siehe <a href="/ultra_guides/de/free-cloud/agnes-ai">Seite</a></td><td><a href="https://platform.agnes-ai.com/settings/apiKeys" target="_blank" rel="noreferrer">platform.agnes-ai.com</a></td></tr><tr><td>Alibaba Bailian (Intl. usw.)</td><td>5</td><td>Registrierung</td><td>Übersicht <a href="/ultra_guides/de/free-cloud/#qwen--alibaba-cloud-bailian">Qwen</a></td><td><a href="https://bailian.console.aliyun.com/" target="_blank" rel="noreferrer">Bailian-Konsole</a></td></tr><tr><td>Zhipu Z AI</td><td>4</td><td>Nein</td><td>Übersicht <a href="/ultra_guides/de/free-cloud/#zhipu-ai-glm">Zhipu</a></td><td><a href="https://open.bigmodel.cn/usercenter/apikeys" target="_blank" rel="noreferrer">open.bigmodel.cn</a></td></tr><tr><td>SambaNova</td><td>4</td><td>Registrierung</td><td>Text</td><td><a href="https://cloud.sambanova.ai/apis" target="_blank" rel="noreferrer">cloud.sambanova.ai</a></td></tr><tr><td>SiliconFlow</td><td>3</td><td>Registrierung</td><td>Übersicht <a href="/ultra_guides/de/free-cloud/#siliconflow">SiliconFlow</a></td><td><a href="https://cloud.siliconflow.cn/account/ak" target="_blank" rel="noreferrer">cloud.siliconflow.cn</a></td></tr><tr><td>xAI / Grok</td><td>3</td><td>Registrierung</td><td>Text (oft Credits)</td><td><a href="https://console.x.ai" target="_blank" rel="noreferrer">console.x.ai</a></td></tr><tr><td>DeepSeek</td><td>2</td><td>Registrierung</td><td>Übersicht <a href="/ultra_guides/de/free-cloud/#deepseek">DeepSeek</a></td><td><a href="https://platform.deepseek.com" target="_blank" rel="noreferrer">platform.deepseek.com</a></td></tr><tr><td>Weitere (Chutes, Glhf, AI21, Nscale, Nebius …)</td><td>wenige</td><td>meist Registrierung</td><td>freellm</td><td>Quick Reference im Repo</td></tr></tbody></table><h3 id="erneuerbare-free-kontingente" tabindex="-1">Erneuerbare Free-Kontingente <a class="header-anchor" href="#erneuerbare-free-kontingente" aria-label="Permalink to &quot;Erneuerbare Free-Kontingente&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Anbieter</th><th>Hinweis</th><th>Handbuch</th></tr></thead><tbody><tr><td>OpenRouter</td><td><code>:free</code>-Pool; ~$10+ kann Free-Tageslimit heben</td><td><a href="/ultra_guides/de/free-cloud/openrouter">OpenRouter</a></td></tr></tbody></table><h2 id="quick-reference-·-base-url-app" tabindex="-1">Quick Reference · Base URL &amp; App <a class="header-anchor" href="#quick-reference-·-base-url-app" aria-label="Permalink to &quot;Quick Reference · Base URL &amp; App&quot;">​</a></h2><p>Meist <strong>Custom (OpenAI)</strong>. Gemini: App-Preset <strong>Gemini(Google)</strong> — nicht OpenAI-Base-URL erzwingen.</p><table tabindex="0"><thead><tr><th>Anbieter</th><th>Base URL (üblich)</th><th>App</th></tr></thead><tbody><tr><td>Groq</td><td><code>https://api.groq.com/openai/v1</code></td><td>Custom (OpenAI)</td></tr><tr><td>SiliconFlow</td><td><code>https://api.siliconflow.cn/v1</code></td><td>Custom (OpenAI)</td></tr><tr><td>Zhipu</td><td><code>https://open.bigmodel.cn/api/paas/v4</code></td><td>Custom (OpenAI)</td></tr><tr><td>Agnes AI</td><td><code>https://apihub.agnes-ai.com/v1</code></td><td>Custom (OpenAI)</td></tr><tr><td>OpenCode Zen</td><td><code>https://opencode.ai/zen/v1</code></td><td>Custom (OpenAI)</td></tr><tr><td>OpenRouter</td><td><code>https://openrouter.ai/api/v1</code></td><td><strong>OpenRouter</strong></td></tr><tr><td>NVIDIA NIM</td><td><code>https://integrate.api.nvidia.com/v1</code></td><td>Custom (OpenAI)</td></tr><tr><td>ModelScope</td><td><code>https://api-inference.modelscope.cn/v1</code></td><td>Custom (OpenAI)</td></tr><tr><td>GitHub Models</td><td><code>https://models.github.ai/inference</code></td><td>Custom (OpenAI)</td></tr><tr><td>Cerebras</td><td><code>https://api.cerebras.ai/v1</code></td><td>Custom (OpenAI)</td></tr><tr><td>SambaNova</td><td><code>https://api.sambanova.ai/v1</code></td><td>Custom (OpenAI)</td></tr><tr><td>Mistral</td><td><code>https://api.mistral.ai/v1</code></td><td>Custom (OpenAI)</td></tr><tr><td>Hugging Face</td><td><code>https://router.huggingface.co/v1</code></td><td>Custom (OpenAI)</td></tr><tr><td>LLM7.io</td><td><code>https://api.llm7.io/v1</code></td><td>Custom (OpenAI)</td></tr><tr><td>Ollama Cloud</td><td><code>https://api.ollama.com</code> (laut Doku)</td><td>Custom (OpenAI)</td></tr><tr><td>Gemini</td><td>Preset</td><td><strong>Gemini(Google)</strong></td></tr><tr><td>DeepSeek</td><td>Preset</td><td><strong>DeepSeek</strong></td></tr><tr><td>Qwen / Bailian</td><td>Preset</td><td><strong>Qwen</strong></td></tr></tbody></table><p>Cloudflare Workers AI braucht <code>{account_id}</code> — bei Unsicherheit zuerst Groq / Zhipu / OpenRouter.</p><p>Lange Key-Links und «beste Free-Modelle»: Repo <a href="https://github.com/open-free-llm-api/awesome-freellm-apis/blob/main/README.zh-CN.md" target="_blank" rel="noreferrer">Best Free Models</a>.</p><h2 id="beliebte-free-modelle-wochennutzung-im-repo" tabindex="-1">Beliebte Free-Modelle (Wochennutzung im Repo) <a class="header-anchor" href="#beliebte-free-modelle-wochennutzung-im-repo" aria-label="Permalink to &quot;Beliebte Free-Modelle (Wochennutzung im Repo)&quot;">​</a></h2><p>Nur «kürzlich genutzt» — <strong>nicht</strong> automatisch bestes Roleplay:</p><table tabindex="0"><thead><tr><th>Richtung</th><th>Beispiele (freellm / Platz-ID)</th></tr></thead><tbody><tr><td>Aggregierter Free-Pool</td><td>OpenRouter: <code>nvidia/nemotron-3-ultra-550b-a55b:free</code> …</td></tr><tr><td>Schnelle Inference</td><td>Groq: <code>llama-3.3-70b-versatile</code>, <code>moonshotai/kimi-k2-instruct</code></td></tr><tr><td>Chinesischer Dialog</td><td>Zhipu Flash, Silicon Free-Tags, Bailian-Neukunden</td></tr><tr><td>Multimodal Text + Bild</td><td><a href="/ultra_guides/de/free-cloud/agnes-ai">Agnes AI</a>, <a href="/ultra_guides/de/free-cloud/aihubmix">AIHubMix</a></td></tr></tbody></table><h2 id="bild-video" tabindex="-1">Bild / Video <a class="header-anchor" href="#bild-video" aria-label="Permalink to &quot;Bild / Video&quot;">​</a></h2><ul><li>Verzeichnis markiert oft <code>image</code> / <code>video</code>; <strong>MiniTavern-Bild</strong> braucht OpenAI-Images-Kompatibilität oder unterstützte Plattformen (<a href="/ultra_guides/de/free-cloud/#kostenlose-bildgenerierung">Kostenlose Bildgenerierung</a>).</li><li>App <strong>ohne Video</strong>; Videomodelle nur Website-Abgleich.</li></ul><h2 id="verwandte-kapitel" tabindex="-1">Verwandte Kapitel <a class="header-anchor" href="#verwandte-kapitel" aria-label="Permalink to &quot;Verwandte Kapitel&quot;">​</a></h2><ul><li><a href="/ultra_guides/de/free-cloud/">Kostenlose Cloud Übersicht</a></li><li><a href="/ultra_guides/de/free-cloud/agnes-ai">Agnes AI</a> · <a href="/ultra_guides/de/free-cloud/opencode-zen">OpenCode Zen</a> · <a href="/ultra_guides/de/free-cloud/aihubmix">AIHubMix</a> · <a href="/ultra_guides/de/free-cloud/openrouter">OpenRouter</a></li><li><a href="/ultra_guides/de/manual/model-link">Modellverbindung</a></li><li><a href="/ultra_guides/de/manual/errors">Fehlercodes</a></li></ul>',28)])])}const g=t(n,[["render",i]]);export{p as __pageData,g as default};
